import{z as s,x as o,o as A,c as n,q as e,j as r,D as E,d as t,s as B,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"偏好数据的来源谱系","description":"","frontmatter":{"title":"偏好数据的来源谱系","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-data-sources.md","filePath":"llm/rm-data-sources.md","lastUpdated":1791413859000}'),d={name:"llm/rm-data-sources.md"};function p(m,a,_,h,D,u){const l=o("Mermaid");return A(),n("div",null,[a[2]||(a[2]=e('<h1 id="偏好数据的来源谱系" tabindex="-1">偏好数据的来源谱系 <a class="header-anchor" href="#偏好数据的来源谱系" aria-label="Permalink to &quot;偏好数据的来源谱系&quot;">​</a></h1><div class="epigraph"><p>奖励模型是比较数据的回归器：数据从哪来，「好」就被定义成什么——先看清楚每一行的偏置，再谈训练。</p><footer>—— 据 Ouyang 等 InstructGPT 2022、Bai 等 Constitutional AI 2022 的数据采集章节整理</footer></div><p><a href="/llm/retrieval-poisoning-defense">上一课</a>把检索投毒的防御收在「可写索引即可被劫持，忠实阅读器会放大毒块」，防线落在鉴权、多源交叉与敏感人审。那是 RAG 课的末尾，也是本课程的起点：凡是「模型读什么就信什么」的地方，数据来源就是第一道工程。本课程打开奖励模型工程。<a href="/llm/reward-model">奖励模型</a>已经在主干把 RM 定义成 \\(r(x,y)\\) 的回归器，本课回答更上游的问题：比较对从哪来。来源决定噪声结构与覆盖面，先钉谱系，后课的配比、标注形态与一致性检验都默认已读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要训 RM，先要有 \\((x, y_w, y_l)\\) 三元组。谁提供 \\(x\\)、谁生成 \\(y\\)、谁判 \\(y_w \\gt y_l\\)，三个空各有几种填法，组合起来就是来源谱系。填错组合的代价不是效果差一点，而是 RM 学到的东西和产品要的东西完全不同：用合成裁判的判断训出来的 RM，优化它会得到「裁判喜欢的回答」，不是「用户喜欢的回答」。所以来源选择是奖励工程里第一个不可逆的决策——后面的损失函数换起来便宜，数据重采很贵。</p><p><span class="marginnote">先翻译一下记号：三元组 \\((x, y_w, y_l)\\) 里，\\(x\\) 是提示，\\(y_w\\) 是这对比拼中获胜的回答（winner），\\(y_l\\) 是落败的回答（loser）。RM 学到的全部知识只有一句话——「在这个提示下，这对里谁该赢」，除此之外它一无所知。</span></p><h3 id="四类来源的填法" tabindex="-1">四类来源的填法 <a class="header-anchor" href="#四类来源的填法" aria-label="Permalink to &quot;四类来源的填法&quot;">​</a></h3><p>人工比较：InstructGPT 让标注员对同一提示下的模型样本排序，Llama 2 采了约 141 万条成对比较。提示可来自真实使用日志或标注员自写，候选通常混采自多个策略版本，避免只含单一模型的怪癖。质量最高、最贵，指南决定一切。</p><p>平台隐式反馈：点踩、点选、停留时长，<a href="/llm/implicit-feedback-prefs">隐式反馈</a>已有主干课。量大、免费，但「点踩」混着质量差与情绪差，选择偏差严重，只能做辅源或评测信号。</p><p>AI 反馈：<a href="/llm/rlaif">RLAIF</a> 与 Constitutional AI 用一个强模型按成文原则替代人。便宜、可无限采、可复现，但裁判的偏差随数据进入 RM；<a href="/llm/llm-judge-bias">LLM 裁判偏差</a>列过的位置、长度、自我偏好一样不少。</p><p>模型自评：<a href="/llm/self-rewarding-lm">自奖励语言模型</a>让策略自己给自己当裁判，闭环最快，分布也收得最快——模型看不见的东西，循环里永远不会出现。</p>',11)),(A(),r(i,null,{default:E(()=>[B(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E6%8F%90%E7%A4%BA%E6%9D%A5%E6%BA%90%EF%BC%9A%E6%97%A5%E5%BF%97%E6%88%96%E8%87%AA%E5%86%99%22%5D%20--%3E%20GEN%5B%22%E5%80%99%E9%80%89%E7%94%9F%E6%88%90%EF%BC%9A%E5%A4%9A%E7%AD%96%E7%95%A5%E6%B7%B7%E9%87%87%22%5D%0A%20%20GEN%20--%3E%20H%5B%22%E4%BA%BA%E5%B7%A5%E6%AF%94%E8%BE%83%22%5D%0A%20%20GEN%20--%3E%20IF%5B%22%E5%B9%B3%E5%8F%B0%E9%9A%90%E5%BC%8F%E5%8F%8D%E9%A6%88%22%5D%0A%20%20GEN%20--%3E%20AF%5B%22AI%20%E5%8F%8D%E9%A6%88%E8%A3%81%E5%88%A4%22%5D%0A%20%20GEN%20--%3E%20SF%5B%22%E6%A8%A1%E5%9E%8B%E8%87%AA%E8%AF%84%22%5D%0A%20%20H%20--%3E%20PAIR%5B%22%E6%AF%94%E8%BE%83%E5%AF%B9%20(x%2C%20y_w%2C%20y_l)%22%5D%0A%20%20IF%20--%3E%20PAIR%0A%20%20AF%20--%3E%20PAIR%0A%20%20SF%20--%3E%20PAIR%0A%20%20PAIR%20--%3E%20RM%5B%22%E5%A5%96%E5%8A%B1%E6%A8%A1%E5%9E%8B%20r(x%2Cy)%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上先钉三件事。其一，提示分布：真实日志保覆盖，但含隐私与毒性，须走同一套<a href="/llm/data-quality-filter">数据清洗</a>；自写提示干净但窄。其二，候选采样：候选应来自当前策略及其近邻版本，RM 要在策略的支撑内分辨好坏，拿两个毫不相干模型的输出做比较，学到的边界用不上。其三，标注协议：成对为主干，四类来源给同一对打的标签不能直接混用——人给的「好一点」和 GPT-4 给的「好一点」不是同一个测量。各来源先各自成池、各自测一致率（后课展开），再按配比进损失。</p><p><span class="marginnote">「在策略的支撑内分辨好坏」可以想象成裁判只看过游泳和跑步选手的比赛，就训不出合格的体操裁判——拿两个毫不相干模型的输出做比较，画出的分界线落在真实用户永远见不到的样本上，这条边界上线即失效。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>来源怎么写进 RM 的行为：比较对定义了损失的经验分布，RM 的容量有限，会先拟合分布里最强的可分特征。人工数据把指南内化成 RM 的价值函数；隐式反馈把平台的界面位置内化进去；AI 反馈把裁判模型的风格偏好内化进去。四类源混训时噪声不独立——同一个裁判模型给整个池子打分，它的系统性偏差在每个样本上同向，等于在损失里加了一项固定偏移，梯度下降只会拟合它。这就是为什么来源谱系要写进数据卡：RM 出问题时，第一件事是回查每一类源各贡献了什么。</p>',5)),(A(),r(i,null,{default:E(()=>[B(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%BA%BA%E5%B7%A5%E6%B1%A0%22%5D%20--%3E%20B1%5B%22%E6%8C%87%E5%8D%97%E6%8E%AA%E8%BE%9E%E5%86%85%E5%8C%96%E6%88%90%E4%BB%B7%E5%80%BC%E5%87%BD%E6%95%B0%22%5D%0A%20%20IF%5B%22%E9%9A%90%E5%BC%8F%E6%B1%A0%22%5D%20--%3E%20B2%5B%22%E7%95%8C%E9%9D%A2%E4%BD%8D%E7%BD%AE%E4%B8%8E%E7%94%A8%E6%88%B7%E6%83%85%E7%BB%AA%E5%86%85%E5%8C%96%22%5D%0A%20%20AF%5B%22AI%20%E6%B1%A0%22%5D%20--%3E%20B3%5B%22%E8%A3%81%E5%88%A4%E6%A8%A1%E5%9E%8B%E7%9A%84%E9%A3%8E%E6%A0%BC%E5%81%8F%E5%A5%BD%E5%86%85%E5%8C%96%22%5D%0A%20%20SF%5B%22%E8%87%AA%E8%AF%84%E6%B1%A0%22%5D%20--%3E%20B4%5B%22%E7%AD%96%E7%95%A5%E5%B7%B2%E6%9C%89%E5%81%8F%E5%A5%BD%E7%9A%84%E9%95%9C%E5%83%8F%22%5D%0A%20%20B1%20--%3E%20MIX%5B%22%E5%9B%9B%E6%B1%A0%E6%B7%B7%E8%AE%AD%22%5D%0A%20%20B2%20--%3E%20MIX%0A%20%20B3%20--%3E%20MIX%0A%20%20B4%20--%3E%20MIX%0A%20%20MIX%20--%3E%20FIX%5B%22%E5%90%8C%E4%B8%80%E8%A3%81%E5%88%A4%E7%9A%84%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E5%B7%AE%E5%90%8C%E5%90%91%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20FIX%20--%3E%20FIT%5B%22%E6%A2%AF%E5%BA%A6%E4%B8%8B%E9%99%8D%E6%8A%8A%E5%9B%BA%E5%AE%9A%E5%81%8F%E7%A7%BB%E6%8B%9F%E5%90%88%E8%BF%9B%20RM%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">一个常见误区：把「点踩多」直接当成「回答差」。点踩率更常混着用户当时的心情、响应等待时长、甚至按钮在界面上放的位置——它测的是人对界面的即时反应，不是回答的客观质量，所以只能当辅源。</span></p><p><span class="marginnote">Llama 2 的比较集约 141 万条，其中有用侧约九成、安全侧约一成；把两类比较拆开采、拆开标，正是承认不同来源的「好」不可互相翻译。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>来源谱系不回答配比：各池占多少、按什么域切分，是下一课的题。也不回答标注形态：成对、列表还是点级，第三课展开。人工源不是零偏差——标注员的雇佣关系、指南措辞、报酬结构都会写进偏好；AI 源更不是，它把裁判的训练数据一起继承。最容易被略过的是隐式反馈：它看似「真实用户」，实则测的是界面反应，不是回答质量，直接喂进 RM 会把产品文案的好感误记为能力。凡是把来源混用的流水线，都要在数据卡上为每一行写清：谁生成、谁判断、判断的锚是什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>比较对来自四类源：人工比较、平台隐式反馈、AI 反馈、模型自评，噪声结构各不相同。</li><li>候选应采自当前策略及其近邻，RM 的分辨边界要在策略支撑内才可用。</li><li>各来源先各自成池、各自测一致率，再按配比混合；标签不可跨源直译。</li><li>来源的系统性偏差会被 RM 拟合成固定项，数据卡必须记录来源与判断锚。</li><li>出处：Ouyang 等 InstructGPT，2022；Touvron 等 Llama 2，2023；Bai 等 Constitutional AI，2022。</li></ul>',6))])}const f=s(d,[["render",p]]);export{F as __pageData,f as default};
